def match(pattern: str, text: str) -> bool:
    """
    Implements a basic regex matching algorithm using recursion with memoization.
    Supports:
    - Literal characters
    - `.` (matches any single character)
    - `*` (matches zero or more of the preceding element)
    - `+` (matches one or more of the preceding element)
    """

    memo = {}

    def dp(p_index: int, t_index: int) -> bool:
        if (p_index, t_index) in memo:
            return memo[(p_index, t_index)]

        if p_index == len(pattern):
            result = t_index == len(text)
        else:
            first_match = (t_index < len(text) and 
                           (pattern[p_index] == text[t_index] or pattern[p_index] == '.'))

            if p_index + 1 < len(pattern):
                if pattern[p_index + 1] == '*':
                    result = (dp(p_index + 2, t_index) or 
                              (first_match and dp(p_index, t_index + 1)))
                elif pattern[p_index + 1] == '+':
                    result = first_match and dp(p_index, t_index + 1)
                else:
                    result = first_match and dp(p_index + 1, t_index + 1)
            else:
                result = first_match and (t_index + 1 == len(text))

        memo[(p_index, t_index)] = result
        return result

    return dp(0, 0)

